{
  "title": "The Glass Diver's Rescue",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "The glass diver arrives at the ruined city gates.",
      "visual_description": "The glass diver stands before the rusted iron gates of the ruined city, his diving helmet reflecting the broken spires and faded royal banners hanging limp in the still air.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 2,
      "caption": "Mara the Cartographer unfolds a worn map.",
      "visual_description": "Mara kneels on a cobblestone street, her ink-stained coat sleeves brushing the ground as she spreads a tattered map across her lap, brass compass gleaming in the pale light.",
      "characters": ["mara_the_cartographer"]
    },
    {
      "scene_number": 3,
      "caption": "The Oracle Lamp flickers a warning.",
      "visual_description": "The Oracle Lamp sits on a broken pillar, its single glowing eye flickering as it casts a pool of amber light onto the crumbling facade of a cursed tower.",
      "characters": ["oracle_lamp"]
    },
    {
      "scene_number": 4,
      "caption": "The Sleeping Tax Collector snores on a pile of ledgers.",
      "visual_description": "A mound of dusty ledgers in a collapsed archive serves as a pillow for the Sleeping Tax Collector, who dozes with stamped papers stuck to his sleeves and a quill tucked behind his ear.",
      "characters": ["sleeping_tax_collector"]
    },
    {
      "scene_number": 5,
      "caption": "The Tin Fox scurries ahead to scout the tower gate.",
      "visual_description": "The Tin Fox darts through a narrow alley, its key-wind tail spinning, blue glass eyes scanning the heavy iron gate at the base of the cursed tower.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 6,
      "caption": "The glass diver peers through a cracked window into the tower.",
      "visual_description": "The glass diver presses his helmet against a shattered window pane, the reflection of the ruined city bending across the curved glass as he peers into the tower's dark interior.",
      "characters": ["glass_diver", "mara_the_cartographer"]
    },
    {
      "scene_number": 7,
      "caption": "Mara traces a secret path on her map.",
      "visual_description": "Mara draws a line with her ink-stained finger across the map, following a hidden route that winds past old royal banners and through a collapsed courtyard.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 8,
      "caption": "The Oracle Lamp warns of an armored patrol approaching.",
      "visual_description": "The Oracle Lamp's flame gutters as it speaks, casting long shadows across the street where the sound of clanking armor echoes from around a corner.",
      "characters": ["oracle_lamp", "glass_diver"]
    },
    {
      "scene_number": 9,
      "caption": "The Sleeping Tax Collector stirs but does not wake.",
      "visual_description": "The Sleeping Tax Collector mumbles in his sleep, shifting on his ledger pillow, but remains oblivious to the danger as the patrol passes nearby.",
      "characters": ["sleeping_tax_collector"]
    },
    {
      "scene_number": 10,
      "caption": "The Tin Fox finds a magic door hidden behind a tapestry.",
      "visual_description": "The Tin Fox noses aside a faded royal banner, revealing a stone door engraved with swirling patterns that pulse with a faint blue light.",
      "characters": ["tin_fox", "mara_the_cartographer"]
    },
    {
      "scene_number": 11,
      "caption": "The glass diver swims through the magic door's surface.",
      "visual_description": "The glass diver places his gloved hand on the magic door, and the stone ripples like water, allowing him to step through into a corridor of mirrors.",
      "characters": ["glass_diver", "tin_fox"]
    },
    {
      "scene_number": 12,
      "caption": "Mara consults the Oracle Lamp inside the mirror corridor.",
      "visual_description": "Mara holds the Oracle Lamp high, its glow reflecting off a thousand mirrored walls, each showing a different angle of the same crumbling hallway.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 13,
      "caption": "The Sleeping Tax Collector is carried along, still asleep.",
      "visual_description": "The glass diver hoists the Sleeping Tax Collector onto his shoulders, the official's ledger book still clutched to his chest as he snores through the rescue.",
      "characters": ["sleeping_tax_collector", "glass_diver"]
    },
    {
      "scene_number": 14,
      "caption": "The Tin Fox triggers a hidden alarm.",
      "visual_description": "The Tin Fox steps on a loose flagstone, and a bell rings somewhere in the tower, echoing through the ruined halls.",
      "characters": ["tin_fox", "oracle_lamp"]
    },
    {
      "scene_number": 15,
      "caption": "The group races down a staircase lined with old royal banners.",
      "visual_description": "The glass diver, Mara, the Sleeping Tax Collector, and the Tin Fox clatter down a spiral staircase, old royal banners brushing their shoulders as they descend.",
      "characters": ["glass_diver", "mara_the_cartographer", "sleeping_tax_collector", "tin_fox"]
    },
    {
      "scene_number": 16,
      "caption": "The Oracle Lamp lights the way to the bridge.",
      "visual_description": "The Oracle Lamp's flame blazes brighter as they reach the base of the tower, casting a path of light across the courtyard toward the stone bridge that spans the chasm.",
      "characters": ["oracle_lamp", "glass_diver", "mara_the_cartographer"]
    },
    {
      "scene_number": 17,
      "caption": "They cross the bridge as the tower crumbles behind them.",
      "visual_description": "The glass diver, Mara, the Sleeping Tax Collector, and the Tin Fox hurry across the ancient bridge, the cursed tower collapsing in a cloud of dust and stone behind them.",
      "characters": ["glass_diver", "mara_the_cartographer", "sleeping_tax_collector", "tin_fox", "oracle_lamp"]
    },
    {
      "scene_number": 18,
      "caption": "The glass diver looks back at the ruined city from the far side.",
      "visual_description": "The glass diver stands on the far side of the bridge, his helmet reflecting the ruined skyline as the dust settles, the Oracle Lamp flickering beside him.",
      "characters": ["glass_diver", "oracle_lamp"]
    }
  ]
}

